// frontend/src/App.js
import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  // --- State for Mining Calculator ---
  const [hashrate, setHashrate] = useState('50');              
  const [powerConsumption, setPowerConsumption] = useState('3000'); 
  const [electricityCost, setElectricityCost] = useState('0.12');   
  const [networkDifficulty, setNetworkDifficulty] = useState('30000000000000');
  const [bitcoinPrice, setBitcoinPrice] = useState('');

  const [results, setResults] = useState(null);

  // --- Fetch Real-Time BTC Price (Optional) ---
  useEffect(() => {
    const fetchBtcPrice = async () => {
      try {
        const response = await fetch(
          'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd'
        );
        const data = await response.json();
        if (data?.bitcoin?.usd) {
          setBitcoinPrice(data.bitcoin.usd.toString());
        } else {
          setBitcoinPrice('27000'); // fallback
        }
      } catch (error) {
        console.error('Error fetching BTC price:', error);
        setBitcoinPrice('27000');
      }
    };
    fetchBtcPrice();
  }, []);

  // --- Bitcoin Mining Calculation ---
  const handleSubmit = (e) => {
    e.preventDefault();

    const hashrateNum = parseFloat(hashrate);
    const powerNum = parseFloat(powerConsumption);
    const elecCostNum = parseFloat(electricityCost);
    const btcPriceNum = parseFloat(bitcoinPrice) || 0;
    const difficultyNum = parseFloat(networkDifficulty);

    // Convert TH/s -> H/s
    const hashrateHs = hashrateNum * 1e12;

    // Constants
    const blockReward = 6.25;
    const blocksPerDay = 144;
    const twoPow32 = 4294967296;

    // Daily BTC
    const dailyBTC = (hashrateHs / (difficultyNum * twoPow32)) * blockReward * blocksPerDay;
    // Revenue
    const dailyRevenue = dailyBTC * btcPriceNum;
    // Electricity
    const dailyElecCost = (powerNum / 1000) * 24 * elecCostNum;
    // Profit
    const dailyProfit = dailyRevenue - dailyElecCost;
    const monthlyProfit = dailyProfit * 30;
    const yearlyProfit = dailyProfit * 365;

    setResults({
      dailyProfit,
      monthlyProfit,
      yearlyProfit,
      dailyBTC,
      dailyRevenue,
      dailyElecCost
    });
  };

  return (
    <div className="app">
      {/* HERO HEADER */}
      <header className="hero-header">
        <div className="hero-content">
          <h1>Bitcoin Mining Profitability Calculator</h1>
          <p>
            Estimate your daily, monthly, and yearly returns using real-time Bitcoin price data 
            and your rig’s specifications. Explore the potential of mining in a few clicks!
          </p>
        </div>
      </header>

      {/* CALCULATOR SECTION */}
      <main className="calc-layout">
        {/* Left Column (Parameters) */}
        <section className="card left-col">
          <h2>Enter Mining Parameters</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="hashrate">Hashrate (TH/s):</label>
              <input
                id="hashrate"
                type="number"
                placeholder="e.g., 50"
                value={hashrate}
                onChange={(e) => setHashrate(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="powerConsumption">Power Consumption (Watts):</label>
              <input
                id="powerConsumption"
                type="number"
                placeholder="e.g., 3000"
                value={powerConsumption}
                onChange={(e) => setPowerConsumption(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="electricityCost">Electricity Cost ($/kWh):</label>
              <input
                id="electricityCost"
                type="number"
                placeholder="e.g., 0.12"
                step="0.01"
                value={electricityCost}
                onChange={(e) => setElectricityCost(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="bitcoinPrice">Bitcoin Price ($):</label>
              <input
                id="bitcoinPrice"
                type="number"
                value={bitcoinPrice}
                onChange={(e) => setBitcoinPrice(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="networkDifficulty">Network Difficulty:</label>
              <input
                id="networkDifficulty"
                type="number"
                placeholder="e.g., 30000000000000"
                value={networkDifficulty}
                onChange={(e) => setNetworkDifficulty(e.target.value)}
                required
              />
            </div>
            <button type="submit" className="calculate-btn">Calculate</button>
          </form>
        </section>

        {/* Right Column (Results) */}
        <section className="card right-col">
          <h2>Results</h2>
          {results ? (
            <div className="results">
              <div className="result-row">
                <span>Daily Profit:</span>
                <strong>${results.dailyProfit.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Monthly Profit:</span>
                <strong>${results.monthlyProfit.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Yearly Profit:</span>
                <strong>${results.yearlyProfit.toFixed(2)}</strong>
              </div>
              <hr />
              <div className="result-row">
                <span>Daily BTC Mined:</span>
                <strong>{results.dailyBTC.toFixed(8)} BTC</strong>
              </div>
              <div className="result-row">
                <span>Daily Revenue:</span>
                <strong>${results.dailyRevenue.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Daily Electricity Cost:</span>
                <strong>${results.dailyElecCost.toFixed(2)}</strong>
              </div>
            </div>
          ) : (
            <p>Enter your mining parameters to see estimated profits.</p>
          )}
        </section>
      </main>

      {/* INFORMATIONAL SECTION */}
      <section className="info-section">
        <div className="info-container">
          <h2>Types of GICs</h2>
          <ul>
            <li><strong>Non-redeemable GICs:</strong> Highest interest rates, but locked until maturity.</li>
            <li><strong>Redeemable GICs:</strong> Flexible withdrawals, usually lower rates.</li>
            <li><strong>Market-linked GICs:</strong> Principal guarantee with market-based returns.</li>
            <li><strong>Cashable GICs:</strong> Withdraw without penalty after a set time.</li>
          </ul>

          <h2>Factors Influencing GIC Rates</h2>
          <ul>
            <li>Bank of Canada policy rate directly impacts GIC rates.</li>
            <li>Longer terms often yield higher interest.</li>
            <li>Deposits might qualify for better rates.</li>
            <li>Competition among banks can affect offers.</li>
          </ul>

          <h2>Investment Protection</h2>
          <p>
            GICs from eligible financial institutions are protected by CDIC insurance up to $100,000. 
            Principal is guaranteed, making GICs a secure investment option.
          </p>

          <h2>FAQs</h2>
          <ul>
            <li>What is a GIC?</li>
            <li>How is interest calculated?</li>
            <li>What terms are available?</li>
            <li>Minimum investment amounts?</li>
          </ul>

          <h2>About</h2>
          <p>
            GICCalculator.ca provides Canadians with free tools to calculate and compare GIC returns.
          </p>

          <h2>Quick Links</h2>
          <ul>
            <li>Calculator</li>
            <li>Blog</li>
            <li>About Us</li>
            <li>Contact</li>
          </ul>

          <p className="disclaimer">
            Disclaimer: This calculator provides estimates only. Consult with your financial institution for actual rates and returns.
          </p>
          <p className="copyright">
            © {new Date().getFullYear()} GICCalculator.ca. All rights reserved.
          </p>
        </div>
      </section>

      {/* FOOTER */}
      <footer className="footer">
        <p>&copy; {new Date().getFullYear()} Bitcoin Mining Calculator</p>
      </footer>
    </div>
  );
}

export default App;
